// GÉNÉRATION DES EMAILS (français) - SALARIÉS NON ATTACHÉS (XSAL)
const TITRES = {
  SALARIE:   '🟡 Rappel - Dossier salarié à compléter',
  SUPERIEUR: '🟠 IMPORTANT - Salariés non attachés (échéance proche ou dépassée)',
  DGA:       '🔴 INFO DGA - Salariés non attachés (mi-délai atteint ou dépassé)'
};

const INTRO = {
  SALARIE:   "Rappel : les dossiers salariés suivants que vous avez créés n'ont toujours pas de document attaché. Merci de les compléter.",
  SUPERIEUR: "Les dossiers salariés suivants n'ont pas de document attaché et l'échéance est proche ou dépassée. Votre action est requise. Le créateur du dossier est en copie de ce message.",
  DGA:       "Information : les dossiers salariés suivants ont atteint la moitié du délai autorisé (ou l'ont dépassée) sans document attaché."
};

function formaterDate(s) {
  if (!s) return 'N/A';
  const d = new Date(s);
  if (isNaN(d) || d.getFullYear() < 1900) return 'N/A';
  return d.toLocaleDateString('fr-FR', { year: 'numeric', month: '2-digit', day: '2-digit' });
}

function formaterDateHeure(s) {
  if (!s) return 'N/A';
  const d = new Date(s);
  if (isNaN(d) || d.getFullYear() < 1900) return 'N/A';
  return d.toLocaleString('fr-FR', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
}

function emoji(j) {
  if (j <= 2) return '🔴';
  if (j === 3) return '🟠';
  if (j === 4) return '🟡';
  return '🔵';
}

function libelleJours(j) {
  if (j < 0)  return `en retard de ${Math.abs(j)} jour(s)`;
  if (j === 0) return "échéance aujourd'hui";
  return `${j} jour(s) restant(s)`;
}

return $input.all().map(item => {
  const data = item.json;
  const dest = data.destinataire_principal;
  const stats = data.statistiques;
  const type = data.type_destinataire;

  const subject = `${TITRES[type]} — ${stats.total_salaries} salarié(s)`;

  let b = `Bonjour ${dest.prenom} ${dest.nom},\n\n`;
  b += `${INTRO[type]}\n\n`;
  b += `═══════════════════════════════════════════════════════════════\n`;
  b += `📊 STATISTIQUES\n`;
  b += `═══════════════════════════════════════════════════════════════\n\n`;
  b += `${emoji(stats.jours_min)} Niveau d'escalade : ${data.niveau_escalade}\n`;
  b += `Total salariés concernés : ${stats.total_salaries}\n`;
  b += `Situation la plus urgente : ${libelleJours(stats.jours_min)}\n`;
  b += `Délai total : ${stats.delai_total} jour(s)\n`;
  if (type === 'DGA') b += `Seuil DGA (mi-délai) : ${stats.seuil_dga} jour(s)\n`;

  b += `\n═══════════════════════════════════════════════════════════════\n`;
  b += `👥 LISTE DES SALARIÉS NON ATTACHÉS\n`;
  b += `═══════════════════════════════════════════════════════════════\n\n`;

  data.salaries.forEach((s, i) => {
    b += `${i + 1}. ${emoji(s.jours_restants)} ${s.nom_complet} (${s.code_salarie})\n`;
    if (s.matricule) b += `   🪪 Matricule : ${s.matricule}\n`;
    if (s.categorie) b += `   📂 Catégorie : ${s.categorie}\n`;
    if (s.poste)     b += `   💼 Poste : ${s.poste}\n`;
    if (s.service)   b += `   🏢 Service : ${s.service}\n`;
    b += `   📅 Date création : ${formaterDateHeure(s.date_creation)}\n`;
    b += `   ⏰ ${libelleJours(s.jours_restants)} (date limite : ${formaterDate(s.date_limite)})\n`;
    if (s.user_createur) {
      b += `   👤 Créé par : ${s.prenom_createur || ''} ${s.nom_createur || ''} (${s.user_createur})\n`;
      if (s.email_createur) b += `   ✉️ Email créateur : ${s.email_createur}\n`;
      if (s.tel_createur)   b += `   📞 Tél créateur : ${s.tel_createur}\n`;
    }
    if (s.jours_restants <= 2) b += `   🚨 URGENT — Attacher immédiatement les documents requis\n`;
    b += `\n`;
  });

  b += `═══════════════════════════════════════════════════════════════\n`;
  if (type === 'DGA') {
    b += `📌 Ces dossiers ont atteint la moitié du délai autorisé. Merci de vous assurer que les actions correctives sont engagées.\n`;
  } else if (stats.jours_min <= 2) {
    b += `🚨 ACTION REQUISE : attacher immédiatement les documents requis aux dossiers salariés.\n`;
  } else {
    b += `📌 Veuillez attacher les documents manquants aux dossiers salariés dans les meilleurs délais.\n`;
  }
  b += `═══════════════════════════════════════════════════════════════\n\n`;
  b += `Cordialement,\n\nService SI/IA — Jbel Annour\n\n`;
  b += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  b += `🤖 Message automatique — ${formaterDate(new Date().toISOString())}\n`;
  b += `Merci de ne pas répondre à cet email\n`;

  return {
    json: {
      ...data,
      messages: { email: { subject, body: b } },
      meta: { ...data.meta, date_generation: new Date().toISOString() }
    }
  };
});

// STRUCTURATION PAR DESTINATAIRE - SALARIÉS NON ATTACHÉS (XSAL)
// Niveaux : SALARIE (J-4) / SUPERIEUR (J-3 ou moins) / DGA (délai/2 ou moins)
const items = $input.all();
const v = x => (x === null || x === undefined) ? '' : x;
const groupes = {};

items.forEach(item => {
  const d = item.json;
  const niveau = d.niveau_escalade;
  let dest;

  if (niveau === 'SALARIE') {
    dest = { code: d.code_createur, nom: d.nom_createur, prenom: d.prenom_createur,
             email: d.email_destinataire || d.email_createur, telephone: d.tel_createur };
  } else if (niveau === 'SUPERIEUR') {
    dest = { code: d.code_sup_createur, nom: d.nom_sup_createur, prenom: d.prenom_sup_createur,
             email: d.email_destinataire || d.email_sup_createur, telephone: d.tel_sup_createur };
  } else if (niveau === 'DGA') {
    dest = { code: d.code_dga, nom: d.nom_dga, prenom: d.prenom_dga,
             email: d.email_destinataire || d.email_dga, telephone: d.telephone_dga };
  } else {
    return;
  }

  const cle = `${niveau}_${dest.code || dest.email || 'INCONNU'}`;

  if (!groupes[cle]) {
    groupes[cle] = {
      destinataire_principal: {
        code: v(dest.code), nom: v(dest.nom), prenom: v(dest.prenom),
        email: v(dest.email), telephone: v(dest.telephone)
      },
      type_destinataire: niveau,
      niveau_escalade: niveau,
      cc: new Set(),
      salaries: []
    };
  }

  // CC : emails (salariés) fournis par la requête
  if (d.email_cc) {
    String(d.email_cc).split(',').map(e => e.trim()).filter(Boolean)
      .forEach(e => groupes[cle].cc.add(e));
  }

  groupes[cle].salaries.push({
    code_salarie:          d['Code Salarié'],
    matricule:             d['Matricule'],
    nom_complet:           d['Nom Complet'],
    email:                 d.email,
    telephone:             d.telephone,
    categorie:             d['Catégorie'],
    poste:                 d['Poste'],
    service:               d['Service'],
    date_creation:         d['Date de création'],
    date_controle:         d['Date de contrôle'],
    date_limite:           d.date_limite,
    jours_depuis_creation: d.jours_depuis_creation,
    jours_restants:        d.jours_restants,
    delai_int:             d.delai_int,
    seuil_dga:             d.seuil_dga,
    user_createur:         d.user_createur,
    nom_createur:          d.nom_createur,
    prenom_createur:       d.prenom_createur,
    email_createur:        d.email_createur,
    tel_createur:          d.tel_createur
  });
});

const resultats = Object.values(groupes).map(g => {
  g.salaries.sort((a, b) => a.jours_restants - b.jours_restants);
  const jours = g.salaries.map(s => s.jours_restants);
  const delaiTotal = parseInt(g.salaries[0].delai_int) || 40;
  return {
    destinataire_principal: g.destinataire_principal,
    type_destinataire: g.type_destinataire,
    niveau_escalade: g.niveau_escalade,
    email_cc: g.cc.size > 0 ? Array.from(g.cc).join(',') : '',
    salaries: g.salaries,
    statistiques: {
      total_salaries: g.salaries.length,
      jours_min: Math.min(...jours),
      jours_max: Math.max(...jours),
      delai_total: delaiTotal,
      seuil_dga: g.salaries[0].seuil_dga
    },
    meta: {
      date_traitement: new Date().toISOString(),
      peut_envoyer_email: !!g.destinataire_principal.email
    }
  };
});

console.log(`Notifications structurées : ${resultats.length}`);
resultats.forEach(r => console.log(`  ${r.type_destinataire} - ${r.destinataire_principal.email || 'SANS EMAIL'} : ${r.statistiques.total_salaries} salarié(s)`));

return resultats.map(r => ({ json: r }));
